"use client";
import { ArrowDown, ArrowUp, ArrowUpDown, ChevronDown, ChevronLeft, ChevronRight, ChevronUp, FileDown, FileSpreadsheet, Printer, RefreshCw, Search, X } from "lucide-react";
import { FormEvent, useCallback, useEffect, useState } from "react";
type Proposal={numero:string;cliente?:string|null;local?:string|null;necessario:string;comprado:string;saldo:string};
type Product={codigo:string;descricao:string;necessario:string;comprado:string;recebido:string;saldo:string;quantidadePropostas:number;propostas:Proposal[]};
type ResponseData={dados:Product[];paginacao:{pagina:number;limite:number;total:number;totalPaginas:number};totais:{produtos:number;propostas:number;quantidadeNecessaria:string;quantidadeComprada:string;saldoPendente:string}};
type Query={busca:string;proposta:string;cliente:string;status:string;pagina:number;limite:number;ordenar:"codigo"|"descricao"|"saldo"|"propostas";direcao:"asc"|"desc"};
const initial:ResponseData={dados:[],paginacao:{pagina:1,limite:50,total:0,totalPaginas:1},totais:{produtos:0,propostas:0,quantidadeNecessaria:"0",quantidadeComprada:"0",saldoPendente:"0"}};
function number(v:string){return Number(v||0).toLocaleString("pt-BR",{maximumFractionDigits:3})}
function queryString(q:Query){const p=new URLSearchParams();Object.entries(q).forEach(([k,v])=>{if(v!=="")p.set(k,String(v))});return p.toString()}
function errorMessage(v:unknown){if(v&&typeof v==="object"&&"message" in v){const m=(v as {message?:string|string[]}).message;return Array.isArray(m)?m.join(". "):m}return undefined}
function SortIcon({active,direction}:{active:boolean;direction:Query["direcao"]}){if(!active)return <ArrowUpDown size={15}/>;return direction==="asc"?<ArrowUp size={15}/>:<ArrowDown size={15}/>}
export function PurchasesPendingProducts(){const[data,setData]=useState(initial);const[query,setQuery]=useState<Query>({busca:"",proposta:"",cliente:"",status:"",pagina:1,limite:50,ordenar:"descricao",direcao:"asc"});const[loading,setLoading]=useState(true);const[error,setError]=useState("");const[open,setOpen]=useState<string|null>(null);
 const load=useCallback(async(q=query)=>{setLoading(true);setError("");try{const r=await fetch(`/api/compras/produtos-pendentes?${queryString(q)}`,{cache:"no-store"});const p:unknown=await r.json();if(!r.ok)throw new Error(errorMessage(p)??"Falha ao carregar produtos pendentes");setData(p as ResponseData)}catch(e){setError(e instanceof Error?e.message:"Falha ao carregar produtos pendentes")}finally{setLoading(false)}},[query]);
 useEffect(()=>{const t=window.setTimeout(()=>void load(),0);return()=>window.clearTimeout(t)},[load]);
 function submit(e:FormEvent){e.preventDefault();const q={...query,pagina:1};setQuery(q);void load(q)}function clear(){const q:Query={busca:"",proposta:"",cliente:"",status:"",pagina:1,limite:50,ordenar:"descricao",direcao:"asc"};setQuery(q);void load(q)}function sort(field:Query["ordenar"]){const q={...query,ordenar:field,direcao:query.ordenar===field&&query.direcao==="asc"?"desc" as const:"asc" as const,pagina:1};setQuery(q)}
 function download(kind:"exportar.xlsx"|"relatorio.pdf"){const link=document.createElement("a");link.href=`/api/compras/produtos-pendentes/${kind}?${queryString({...query,pagina:1,limite:500})}`;link.download="";document.body.appendChild(link);link.click();link.remove()}
 return <main className="mx-auto max-w-[1700px] space-y-5 print:max-w-none"><header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="font-semibold text-red-600">Compras</p><h1 className="text-3xl font-bold">Produtos pendentes</h1><p className="mt-1 text-sm text-slate-500">Materiais consolidados por produto, com rastreabilidade por proposta.</p></div><div className="flex flex-wrap gap-2 print:hidden"><button onClick={()=>void load()} disabled={loading} className="inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 font-semibold"><RefreshCw className={`h-4 w-4 ${loading?"animate-spin":""}`}/>Atualizar</button><button onClick={()=>window.print()} className="inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 font-semibold"><Printer className="h-4 w-4"/>Imprimir</button><button onClick={()=>download("relatorio.pdf")} className="inline-flex items-center gap-2 rounded-xl border px-4 py-2.5 font-semibold"><FileDown className="h-4 w-4"/>PDF</button><button onClick={()=>download("exportar.xlsx")} className="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-4 py-2.5 font-semibold text-white"><FileSpreadsheet className="h-4 w-4"/>XLSX</button></div></header>
 <form onSubmit={submit} className="grid gap-3 rounded-2xl border bg-white p-4 md:grid-cols-2 xl:grid-cols-[1fr_180px_1fr_190px_auto] dark:border-slate-800 dark:bg-slate-950 print:hidden"><label className="relative"><span className="sr-only">Produto</span><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400"/><input value={query.busca} onChange={e=>setQuery(q=>({...q,busca:e.target.value}))} placeholder="Código ou descrição do produto" className="w-full rounded-xl border bg-transparent py-2.5 pl-10 pr-3"/></label><input value={query.proposta} onChange={e=>setQuery(q=>({...q,proposta:e.target.value}))} placeholder="Proposta" className="rounded-xl border bg-transparent px-3 py-2.5"/><input value={query.cliente} onChange={e=>setQuery(q=>({...q,cliente:e.target.value}))} placeholder="Cliente" className="rounded-xl border bg-transparent px-3 py-2.5"/><select value={query.status} onChange={e=>setQuery(q=>({...q,status:e.target.value}))} className="rounded-xl border bg-transparent px-3"><option value="">Todos pendentes</option><option value="PENDENTE">Pendente</option><option value="COMPRA_PARCIAL">Compra parcial</option></select><div className="flex gap-2"><button className="rounded-xl bg-red-600 px-4 py-2.5 font-semibold text-white">Filtrar</button><button type="button" onClick={clear} aria-label="Limpar filtros" className="rounded-xl border p-2.5"><X/></button></div></form>
 {error&&<div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4 text-red-700">{error}</div>}
 <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{[["Produtos",data.totais.produtos],["Propostas",data.totais.propostas],["Quantidade necessária",number(data.totais.quantidadeNecessaria)],["Quantidade comprada",number(data.totais.quantidadeComprada)],["Saldo pendente",number(data.totais.saldoPendente)]].map(([l,v])=><article key={l} className="rounded-2xl border bg-white p-4 dark:border-slate-800 dark:bg-slate-950"><p className="text-xs font-bold uppercase tracking-wide text-slate-500">{l}</p><p className="mt-2 text-2xl font-bold">{v}</p></article>)}</section>
 <section className="overflow-hidden rounded-2xl border bg-white dark:border-slate-800 dark:bg-slate-950"><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead className="bg-slate-50 text-left dark:bg-slate-900"><tr><th className="px-4 py-3"><button onClick={()=>sort("codigo")} className="inline-flex gap-1">Código<SortIcon active={query.ordenar==="codigo"} direction={query.direcao}/></button></th><th className="px-4 py-3"><button onClick={()=>sort("descricao")} className="inline-flex gap-1">Produto<SortIcon active={query.ordenar==="descricao"} direction={query.direcao}/></button></th><th className="px-4 py-3"><button onClick={()=>sort("propostas")} className="inline-flex gap-1">Propostas<SortIcon active={query.ordenar==="propostas"} direction={query.direcao}/></button></th><th className="px-4 py-3">Necessário</th><th className="px-4 py-3">Comprado</th><th className="px-4 py-3">Recebido</th><th className="px-4 py-3"><button onClick={()=>sort("saldo")} className="inline-flex gap-1">Saldo<SortIcon active={query.ordenar==="saldo"} direction={query.direcao}/></button></th><th className="w-12 print:hidden"></th></tr></thead><tbody className="divide-y dark:divide-slate-800">{data.dados.map(item=><tr key={`${item.codigo}-${item.descricao}`} className="align-top"><td className="px-4 py-3 font-semibold">{item.codigo}</td><td className="min-w-80 px-4 py-3">{item.descricao}{open===item.codigo&&<div className="mt-3 rounded-xl bg-slate-50 p-3 dark:bg-slate-900"><b>Distribuição por proposta</b><div className="mt-2 space-y-2">{item.propostas.map((p,i)=><div key={`${p.numero}-${i}`} className="grid gap-1 border-t pt-2 text-xs sm:grid-cols-[100px_1fr_100px_100px]"><strong>#{p.numero}</strong><span>{p.cliente??"—"} · {p.local??"—"}</span><span>Nec.: {number(p.necessario)}</span><span>Saldo: {number(p.saldo)}</span></div>)}</div></div>}</td><td className="px-4 py-3">{item.quantidadePropostas}</td><td className="px-4 py-3">{number(item.necessario)}</td><td className="px-4 py-3">{number(item.comprado)}</td><td className="px-4 py-3">{number(item.recebido)}</td><td className="px-4 py-3 font-bold text-red-600">{number(item.saldo)}</td><td className="px-4 py-3 print:hidden"><button onClick={()=>setOpen(open===item.codigo?null:item.codigo)} aria-label="Exibir propostas">{open===item.codigo?<ChevronUp/>:<ChevronDown/>}</button></td></tr>)}</tbody></table></div><footer className="flex flex-col gap-3 border-t p-4 text-sm sm:flex-row sm:items-center sm:justify-between print:hidden"><span>Página {data.paginacao.pagina} de {data.paginacao.totalPaginas} · {data.paginacao.total} produtos</span><div className="flex gap-2"><select value={query.limite} onChange={e=>setQuery(q=>({...q,limite:Number(e.target.value),pagina:1}))} className="rounded-lg border bg-transparent px-3"><option value="25">25</option><option value="50">50</option><option value="100">100</option><option value="500">500</option></select><button disabled={loading||query.pagina<=1} onClick={()=>setQuery(q=>({...q,pagina:q.pagina-1}))} className="rounded-lg border p-2 disabled:opacity-40"><ChevronLeft/></button><button disabled={loading||query.pagina>=data.paginacao.totalPaginas} onClick={()=>setQuery(q=>({...q,pagina:q.pagina+1}))} className="rounded-lg border p-2 disabled:opacity-40"><ChevronRight/></button></div></footer></section></main>}
